#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4
ENV_FILE="$HOME/.config/mediamtx-monitoring/collector.env"
settings_dir="${ENV_FILE%/*}"
umask 077
if [[ -L "$settings_dir" || -L "$ENV_FILE" ]]; then
  warn "The settings directory and credentials file must not be symlinks."
  exit 1
fi
mkdir -p "$settings_dir"
[[ -O "$settings_dir" ]] || { warn "Use a settings directory owned by your account."; exit 1; }
chmod 700 "$settings_dir"
if [[ -e "$ENV_FILE" ]]; then
  [[ -f "$ENV_FILE" && -O "$ENV_FILE" ]] || { warn "Use a regular credentials file owned by your account."; exit 1; }
  chmod 600 "$ENV_FILE"
fi

banner "Grafana Cloud VM and service monitoring"

stage "Create the Free stack and restrict access"
open_url "https://grafana.com/auth/sign-up/create-user"
step "Create your account, or sign in to an existing account."
step "Select a Cloud Free stack. Keep the Free plan after any trial. Do not enable a paid upgrade."
step "Keep the stack limited to your account and at most two other named administrators."
step "In the stack, open Administration, then Users and access, to check its users."
step "Keep anonymous access and public dashboard sharing disabled."
step "Copy the stack URL from the browser address bar, without a dashboard path."
ask GRAFANA_STACK_URL "Stack URL, such as https://example.grafana.net:"
GRAFANA_STACK_URL="${GRAFANA_STACK_URL%/}"
[[ "$GRAFANA_STACK_URL" =~ ^https://[a-zA-Z0-9-]+\.grafana\.net$ ]] || { warn "Enter the HTTPS grafana.net stack URL."; exit 1; }
write_env GRAFANA_STACK_URL "$GRAFANA_STACK_URL"

stage "Copy the metrics connection and create its write token"
open_url "https://grafana.com/profile/org"
step "Select your stack. Open Details for Prometheus to find its connection settings."
step "Copy the remote write URL and the numeric instance ID from the Alloy configuration example."
ask GRAFANA_METRICS_URL "Prometheus remote write HTTPS URL:"
[[ "$GRAFANA_METRICS_URL" =~ ^https://[a-zA-Z0-9.-]+\.grafana\.net/api/prom/push$ ]] || { warn "Enter the Cloud Prometheus HTTPS URL ending in /api/prom/push."; exit 1; }
ask GRAFANA_METRICS_USER "Prometheus instance ID:"
[[ "$GRAFANA_METRICS_USER" =~ ^[0-9]+$ ]] || { warn "The instance ID must contain digits only."; exit 1; }
write_env GRAFANA_METRICS_URL "$GRAFANA_METRICS_URL"
write_env GRAFANA_METRICS_USER "$GRAFANA_METRICS_USER"
open_url "$GRAFANA_STACK_URL"
step "Open Administration, then Users and access, then Cloud access policies."
step "Select Create access policy. Name it mediamtx-vm-metrics and select only metrics:write."
step "Create the policy in this stack. Select Add token and set an expiry date."
step "Record the renewal date in your password manager. Copy the new token."
ask_secret GRAFANA_METRICS_TOKEN "Paste the token. Input is hidden:"
[[ "$GRAFANA_METRICS_TOKEN" =~ ^[a-zA-Z0-9_./+=-]+$ ]] || { warn "The token must be one line without spaces or quotes."; exit 1; }
write_env GRAFANA_METRICS_TOKEN "$GRAFANA_METRICS_TOKEN"
unset GRAFANA_METRICS_TOKEN

stage "Copy the logs connection and create its write token"
open_url "https://grafana.com/profile/org"
step "Select the same stack. Open Details for Loki. Copy the push URL and numeric instance ID."
ask GRAFANA_LOGS_URL "Loki push HTTPS URL:"
[[ "$GRAFANA_LOGS_URL" =~ ^https://[a-zA-Z0-9.-]+\.grafana\.net/loki/api/v1/push$ ]] || { warn "Enter the Cloud Loki HTTPS URL ending in /loki/api/v1/push."; exit 1; }
ask GRAFANA_LOGS_USER "Loki instance ID:"
[[ "$GRAFANA_LOGS_USER" =~ ^[0-9]+$ ]] || { warn "The instance ID must contain digits only."; exit 1; }
write_env GRAFANA_LOGS_URL "$GRAFANA_LOGS_URL"
write_env GRAFANA_LOGS_USER "$GRAFANA_LOGS_USER"
open_url "$GRAFANA_STACK_URL"
step "Open Administration, Users and access, Cloud access policies."
step "Create a stack-scoped policy named mediamtx-service-logs with only logs:write."
step "Add a token with an expiry date. Record the renewal date in your password manager."
ask_secret GRAFANA_LOGS_TOKEN "Paste the logs token. Input is hidden:"
[[ "$GRAFANA_LOGS_TOKEN" =~ ^[a-zA-Z0-9_./+=-]+$ ]] || { warn "The token must be one line without spaces or quotes."; exit 1; }
write_env GRAFANA_LOGS_TOKEN "$GRAFANA_LOGS_TOKEN"
unset GRAFANA_LOGS_TOKEN

stage "Save the VM label and continue with deployment"
ask MONITORING_INSTANCE "Stable VM label. Enter uses viewer-vm:"
MONITORING_INSTANCE="${MONITORING_INSTANCE:-viewer-vm}"
[[ "$MONITORING_INSTANCE" =~ ^[a-zA-Z0-9][a-zA-Z0-9._-]{0,62}$ ]] || { warn "Use 1 to 63 letters, digits, dots, underscores, or hyphens, starting with a letter or digit."; exit 1; }
write_env MONITORING_INSTANCE "$MONITORING_INSTANCE"
chmod 600 "$ENV_FILE"
note "Saved locally: $ENV_FILE"
note "Give the agent the VM SSH target and this file path. Keep the token out of chat."
note "For manual deployment, follow deploy/monitoring/README.md in this repository."
note "The guide includes VM capacity checks, dashboard import, and access checks."
note "Cloud delivery and VM headroom are still unverified."
pause "Press Enter to finish local setup."
finish
